import SwiftUI

@main
struct HostApp: App {
    var body: some Scene {
        WindowGroup {
            Text("host")
        }
    }
}

import XCTest

final class HostAppUITests: XCTestCase {
    func testDumpHierarchy() throws {
        let bluesky = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        bluesky.activate()

        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let openButton = springboard.buttons["Open"]
        if openButton.waitForExistence(timeout: 3) {
            openButton.tap()
        }

        XCTAssertTrue(bluesky.waitForState(.runningForeground, timeout: 10))
        Thread.sleep(forTimeInterval: 2)

        let dump = bluesky.debugDescription
        let fm = FileManager.default
        let docs = fm.urls(for: .documentDirectory, in: .userDomainMask)[0]
        try dump.write(to: docs.appendingPathComponent("uidump.txt"), atomically: true, encoding: .utf8)
        try dump.write(to: fm.temporaryDirectory.appendingPathComponent("uidump.txt"), atomically: true, encoding: .utf8)
    }
}

