import XCTest

final class HostAppUITests: XCTestCase {
    func testOpenSettingsViaDrawer() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()

        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        if springboard.buttons["Open"].waitForExistence(timeout: 2) {
            springboard.buttons["Open"].tap()
        }

        let goBack = app.buttons["Go back"]
        if goBack.waitForExistence(timeout: 3) {
            goBack.tap()
            Thread.sleep(forTimeInterval: 1.5)
        }

        let menuById = app.buttons["menuBtn"]
        let menuByLabel = app.buttons["Menu"]
        let hamburger: XCUIElement
        if menuById.waitForExistence(timeout: 5) {
            hamburger = menuById
        } else if menuByLabel.exists {
            hamburger = menuByLabel
        } else {
            let fm = FileManager.default
            let docs = fm.urls(for: .documentDirectory, in: .userDomainMask)[0]
            try app.debugDescription.write(to: docs.appendingPathComponent("uidump2.txt"), atomically: true, encoding: .utf8)
            XCTFail("hamburger not found")
            return
        }
        hamburger.tap()

        let settings = app.buttons["menuItemButton-Settings"]
        XCTAssertTrue(settings.waitForExistence(timeout: 5))
        var opened = false
        for _ in 0..<40 {
            if settings.frame.minX >= 0 {
                opened = true
                break
            }
            Thread.sleep(forTimeInterval: 0.25)
        }
        XCTAssertTrue(opened, "drawer did not open")
        settings.tap()

        XCTAssertTrue(app.staticTexts["Settings"].waitForExistence(timeout: 5))
        Thread.sleep(forTimeInterval: 1)
    }
}
